#include <stdint.h>
#include <string.h>
#include <psp2/io/fcntl.h>
#include <psp2/kernel/threadmgr.h>
#include "gate1c_protocol.h"
static VbeG1cRecord records[VBE_G1C_CAPACITY];static int write_all(int fd,const void *ptr,unsigned n){const uint8_t *p=(const uint8_t*)ptr;while(n){int r=sceIoWrite(fd,p,n);if(r<=0)return -1;p+=r;n-=(unsigned)r;}return 0;}
int main(int argc,char **argv){VbeG1cStatus st;VbeG1cDumpHeader h;uint32_t n=0,i;int fd;(void)argc;(void)argv;if(vbeG1cPause()<0)return 10;for(i=0;i<2000u;i++){if(vbeG1cGetStatus(&st)<0)return 11;if(st.lifecycle==VBE_OBSERVER_PAUSED&&st.active_producers==0)break;sceKernelDelayThread(1000);}if(st.lifecycle!=VBE_OBSERVER_PAUSED||st.active_producers)return 12;if(st.version!=VBE_G1C_VERSION||st.firmware_version!=VBE_G1C_FW_365)return 13;if(st.missing_required_mask||st.hook_fail_mask||st.lost_records||st.baseline_mismatch_count)return 14;if(vbeG1cRead(records,VBE_G1C_CAPACITY,&n)<0)return 15;memset(&h,0,sizeof(h));h.magic=VBE_G1C_DUMP_MAGIC;h.version=VBE_G1C_VERSION;h.header_size=sizeof(h);h.status_size=sizeof(st);h.record_size=sizeof(VbeG1cRecord);h.record_count=n;h.required_hook_mask=st.required_hook_mask;h.missing_required_mask=st.missing_required_mask;h.lost_records=st.lost_records;h.ring_epoch=st.ring_epoch;h.lifecycle=st.lifecycle;h.baseline_mismatch_count=st.baseline_mismatch_count;fd=sceIoOpen("ux0:data/vbe_gate1c_stage_probe.bin",SCE_O_WRONLY|SCE_O_CREAT|SCE_O_TRUNC,0666);if(fd<0)return 16;if(write_all(fd,&h,sizeof(h))<0||write_all(fd,&st,sizeof(st))<0||write_all(fd,records,n*sizeof(VbeG1cRecord))<0){sceIoClose(fd);return 17;}sceIoClose(fd);if(vbeG1cReset(1)<0)return 18;return 0;}
